function parseMoneyValue(value){
 const raw=String(value??'').replace(/\s|€/g,'').trim();
 if(!raw)return null;
 const lastComma=raw.lastIndexOf(','),lastDot=raw.lastIndexOf('.');
 let normalized=raw;
 if(lastComma>=0&&lastDot>=0){const decimal=lastComma>lastDot?',':'.';const thousands=decimal===','?'.':',';normalized=raw.split(thousands).join('').replace(decimal,'.');}
 else if(lastComma>=0||lastDot>=0){const separator=lastComma>=0?',':'.';const parts=raw.split(separator);const decimals=parts[parts.length-1];normalized=parts.length===2&&decimals.length===3?parts.join(''):raw.replace(separator,'.');}
 const amount=Number(normalized);return Number.isFinite(amount)?amount:null;
}
function formatMoneyValue(value){const amount=parseMoneyValue(value);return amount===null?'':new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2}).format(amount)+' €'}
