async function addKurroOption(kind,selectId,label){const name=prompt(label);if(!name)return;const clean=kind==='provider'?canonicalProvider(name):kind==='owner'?canonicalOwner(name):kind==='category'?canonicalCategory(name):name.trim();if(!clean)return;const values=[...(remoteKurroLists[kind]||[])].map(value=>kind==='provider'?canonicalProvider(value):kind==='owner'?canonicalOwner(value):kind==='category'?canonicalCategory(value):String(value||'').trim());const existing=values.find(value=>value.toLocaleLowerCase('es')===clean.toLocaleLowerCase('es'));if(existing){refreshKurroPeopleOptions();if($(selectId))$(selectId).value=existing;showSyncToast(`${existing} ya estaba en la lista`);return}if(!firebaseUser||!appRevision){showSyncToast('Actualiza los datos de Firebase antes de añadirlo');return}const payload=structuredClone(appDocument);payload.lists=structuredClone(remoteKurroLists||{});payload.lists[kind]=[...values,clean];payload.updated=new Date().toISOString();payload.lastMutation=crypto.randomUUID();try{const confirmed=await writeDocument('appState','main',payload,appRevision);applyConfirmedDocument(confirmed);if($(selectId))$(selectId).value=clean;showSyncToast(`${clean} añadido y guardado`)}catch(error){showSyncToast(error.message==='CONFLICT'?'Los datos han cambiado. Pulsa Actualizar y vuelve a intentarlo.':'No se ha podido guardar la opción')}}
