function analysisAmount(value){return parseMoneyValue(value)||0}
function analysisDate(row){return String(row.orderDate||row.date||'').trim()}
function analysisYear(row){const match=analysisDate(row).match(/(\d{4})$/);return match?match[1]:'Sin año'}
function analysisCurrency(amount){return new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(amount||0)}
function renderAnalysisBars(nodeId,entries,total,emptyLabel){
 const node=$(nodeId);if(!node)return;
 if(!entries.length){node.innerHTML=`<p class="empty">${emptyLabel}</p>`;return}
 node.innerHTML=entries.slice(0,8).map(([label,value])=>{const percent=total?Math.max(3,(value/total)*100):0;return `<div class="analysis-bar-row"><div class="analysis-bar-label"><span>${htmlEscape(label)}</span><strong>${analysisCurrency(value)}</strong></div><div class="analysis-bar-track"><span class="analysis-bar-fill" style="width:${Math.min(100,percent)}%"></span></div></div>`}).join('');
}
function renderProviderAnalysisBars(entries,total,rows){
 const node=$('analysis-provider-chart');if(!node)return;
 if(!entries.length){node.innerHTML='<p class="empty">No hay proveedores para este filtro.</p>';return}
 const counts=new Map();rows.forEach(row=>{const label=String(row.provider||'Sin indicar').trim()||'Sin indicar';counts.set(label,(counts.get(label)||0)+1)});
 node.innerHTML=entries.slice(0,8).map(([label,value])=>{const percent=total?Math.max(3,(value/total)*100):0;const count=counts.get(label)||0;return `<div class="analysis-bar-row"><div class="analysis-bar-label"><button type="button" class="analysis-provider-link" data-provider-filter="${htmlEscape(label)}">${htmlEscape(label)}</button><strong>${analysisCurrency(value)} · ${count} registros</strong></div><div class="analysis-bar-track"><span class="analysis-bar-fill" style="width:${Math.min(100,percent)}%"></span></div></div>`}).join('');
 node.querySelectorAll('[data-provider-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=$('improvement-provider-filter');if(filter){filter.value=button.dataset.providerFilter||'all';document.querySelector('[data-view="improvements"]')?.click();renderImprovements()}}));
}
