 categorySelect.innerHTML='<option value="all">Todas las categorías</option>'+categories.map(item=>`<option value="${htmlEscape(item)}">${htmlEscape(item)}</option>`).join('');categorySelect.value=categories.includes(selected.category)?selected.category:'all';
