 const total=filtered.reduce((sum,row)=>sum+analysisAmount(row.amount),0),fixed=filtered.filter(row=>String(row.expenseType||'').toLocaleLowerCase('es')==='fijo').reduce((sum,row)=>sum+analysisAmount(row.amount),0),extra=filtered.filter(row=>String(row.expenseType||'').toLocaleLowerCase('es')==='extra').reduce((sum,row)=>sum+analysisAmount(row.amount),0),finished=filtered.filter(row=>String(row.status||'').toLocaleLowerCase('es')==='finalizado').length,pending=filtered.filter(row=>!['finalizado','descartado'].includes(String(row.status||'').toLocaleLowerCase('es'))).length;
 const metrics=$('analysis-metrics');if(metrics)metrics.innerHTML=`<div class="metric"><span class="metric-label">Total filtrado</span><strong class="metric-value">${analysisCurrency(total)}</strong><small class="metric-note">${filtered.length} registros</small></div><div class="metric"><span class="metric-label">Gasto fijo</span><strong class="metric-value">${analysisCurrency(fixed)}</strong><small class="metric-note">Tipo fijo</small></div><div class="metric"><span class="metric-label">Gasto extra</span><strong class="metric-value">${analysisCurrency(extra)}</strong><small class="metric-note">Tipo extra</small></div><div class="metric"><span class="metric-label">Pendientes</span><strong class="metric-value">${pending}</strong><small class="metric-note">${finished} finalizadas</small></div>`;
 const aggregate=(key)=>{const map=new Map();filtered.forEach(row=>{const label=String(row[key]||'Sin indicar').trim()||'Sin indicar';map.set(label,(map.get(label)||0)+analysisAmount(row.amount))});return [...map.entries()].sort((a,b)=>b[1]-a[1])};
 const categoryEntries=aggregate('category');
 const palette=['#2f8069','#e47752','#6c8fbd','#c9a34e','#7c6db2','#4d9aa5','#d17a9c','#7c8d91'];
 const categoryNode=$('analysis-category-chart');
 if(categoryNode){if(!categoryEntries.length)categoryNode.innerHTML='<p class="empty">No hay importes para este filtro.</p>';else{let cursor=0;const stops=categoryEntries.slice(0,8).map(([label,value],i)=>{const start=cursor;cursor+=total?(value/total)*360:0;return `${palette[i%palette.length]} ${start}deg ${cursor}deg`}).join(',');categoryNode.innerHTML=`<div class="analysis-donut-wrap"><div class="analysis-donut" style="background:conic-gradient(${stops})"><span>${analysisCurrency(total)}</span></div><div class="analysis-legend">${categoryEntries.slice(0,8).map(([label,value],i)=>`<div><i style="background:${palette[i%palette.length]}"></i><span>${htmlEscape(label)}</span><strong>${analysisCurrency(value)} · ${Math.round(total?(value/total)*100:0)}%</strong></div>`).join('')}</div></div>`}}
 const selectedAnalysisYear=yearSelect.value,periodSelect=$('analysis-period-mode'),periodMode=periodSelect?.value||'extra';if(periodSelect){periodSelect.disabled=selectedAnalysisYear==='all';periodSelect.closest('.analysis-period-control')?.classList.toggle('is-hidden',selectedAnalysisYear==='all')}
 const yearTotals=new Map();filtered.forEach(row=>{const label=analysisYear(row);yearTotals.set(label,(yearTotals.get(label)||0)+analysisAmount(row.amount))});
 let periodEntries=[...yearTotals.entries()].sort((a,b)=>String(a[0]).localeCompare(String(b[0]))),periodEmpty='No hay años para este filtro.';
