 renderProviderAnalysisBars(aggregate('provider'),total,filtered);
 const expenseEntries=['Fijo','Extra'].map(label=>[label,filtered.filter(row=>String(row.expenseType||'').toLocaleLowerCase('es')===label.toLocaleLowerCase('es')).reduce((sum,row)=>sum+analysisAmount(row.amount),0)]).filter(([,value])=>value>0);
 const expenseNode=$('analysis-expense-chart');
