 const top=$('analysis-top-table');if(top){const rows=[...filtered].sort((a,b)=>analysisAmount(b.amount)-analysisAmount(a.amount)).slice(0,10);top.innerHTML=rows.length?rows.map(row=>`<tr><td>${htmlEscape(row.name||'Sin indicar')}</td><td>${htmlEscape(row.category||'Sin indicar')}</td><td>${htmlEscape(row.provider||'Sin indicar')}</td><td>${htmlEscape(row.orderNumber||'Sin indicar')}</td><td>${htmlEscape(analysisDate(row)||'Sin fecha')}</td><td>${htmlEscape(improvementAmount(row.amount))}</td><td>${htmlEscape(row.expenseType||'Sin indicar')}</td><td><span class="status ${improvementStatusClass(row.status)}">${htmlEscape(row.status||'Necesidad detectada')}</span></td></tr>`).join(''):'<tr><td colspan="8" class="empty">No hay compras que coincidan con los filtros.</td></tr>'}
