function providerContactMatchKey(value){return canonicalProvider(value).toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}
function purchaseProviderContactGroup(provider){const raw=canonicalProvider(provider);if(!raw)return'';const target=providerContactMatchKey(raw);const key=Object.keys(providerContactsByName||{}).find(name=>name!==INTERNAL_CONTACTS_KEY&&providerContactMatchKey(name)===target);return key||raw}
function purchaseProviderContacts(provider){const group=purchaseProviderContactGroup(provider);return group?(providerContactsByName[group]||[]):[]}
function purchaseProviderOptions(){return providerDirectoryRows().map(row=>row.name).filter(Boolean).sort((a,b)=>a.localeCompare(b,'es',{sensitivity:'base'}))}
function refreshImprovementProviderOptions(current=''){const select=$('improvement-edit-provider');if(!select)return;const value=current||select.value;select.innerHTML='<option value="">Sin proveedor seleccionado</option>'+purchaseProviderOptions().map(v=>`<option value="${htmlEscape(v)}">${htmlEscape(v)}</option>`).join('');if(value){const match=purchaseProviderOptions().find(v=>v.toLocaleLowerCase('es')===value.toLocaleLowerCase('es'));if(match)select.value=match;else{const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option);select.value=value}}}
function refreshImprovementSupplierNumber(){const provider=canonicalProvider($('improvement-edit-provider')?.value),field=$('improvement-edit-supplier');if(!field||!provider)return;const row=providerDirectoryRows().find(item=>canonicalProvider(item.name)===provider);if(row?.supplierNumber)field.value=row.supplierNumber}
function renderImprovementContactDetails(){const details=$('improvement-edit-contact-details'),select=$('improvement-edit-contact'),contact=purchaseProviderContacts($('improvement-edit-provider')?.value).find(c=>c.id===select?.value);if(!details)return;if(!contact){details.innerHTML='<span class="provider-contact-empty">Elige un contacto del proveedor o completa los datos manualmente.</span>';return}details.innerHTML=[`<strong>${htmlEscape(contact.name||'Contacto')}</strong>`,contact.role?`<span class="provider-contact-role">${htmlEscape(contact.role)}</span>`:'',contact.phone?`<a href="tel:${htmlEscape(contact.phone)}">${htmlEscape(contact.phone)}</a>`:'',contact.email?contactEmailLinks(contact.email,'provider-contact-link',`Enviar correo a ${htmlEscape(contact.name||'Contacto')}`):''].filter(Boolean).join('<span> · </span>')||'<span class="provider-contact-empty">Sin datos de contacto guardados.</span>'}
function refreshImprovementContacts(selectedId=''){const select=$('improvement-edit-contact');if(!select)return;const contacts=purchaseProviderContacts($('improvement-edit-provider')?.value);select.innerHTML='<option value="">Sin contacto seleccionado</option>'+contacts.map(c=>`<option value="${htmlEscape(c.id)}" data-contact-meta="${htmlEscape([c.role,c.phone,c.email].filter(Boolean).join(' · '))}">${htmlEscape(c.name)}</option>`).join('');if(selectedId&&contacts.some(c=>c.id===selectedId))select.value=selectedId;renderImprovementContactDetails()}
function improvementPhotoValues(row,kind){const list=kind==='before'?row.beforeUrls:row.afterUrls;const legacy=kind==='before'?row.beforeUrl:row.afterUrl;return Array.isArray(list)?list.filter(Boolean):legacy?[legacy]:[]}
function renderImprovementPhotoFields(kind,values=[]){const list=$(kind==='before'?'improvement-before-list':'improvement-after-list');if(!list)return;const urls=values.length?values:[''];list.innerHTML=urls.map((url,index)=>`<div class="improvement-photo-editor-row"><input type="url" inputmode="url" data-photo-input="${kind}" data-photo-index="${index}" value="${htmlEscape(url)}" placeholder="Pega el enlace de la foto ${kind==='before'?'anterior':'posterior'}"><button type="button" class="secondary improvement-photo-remove" data-photo-remove="${kind}" ${urls.length===1?'hidden':''}>Quitar</button></div>`).join('')}
function readImprovementPhotoValues(kind){return [...document.querySelectorAll(`[data-photo-input="${kind}"]`)].map(input=>input.value.trim()).filter(Boolean)}
